func (g *DeltaNetGPU) Carry() {
	c := g.cfg
	hist := c.Conv - 1
	rows := g.abuf.ReadFloat32At(int(g.aQKV)+(g.rows-hist)*g.qkvN(), hist*g.qkvN())
	g.abuf.WriteFloat32At(int(g.aQKVBase), rows)
