#version 450

#extension GL_EXT_shader_16bit_storage : enable
#extension GL_EXT_shader_explicit_arithmetic_types_float16 : enable

// The PLE block's fourth dispatch, and the only one that exists so that a
// *next* run can happen: it stores this run's last `(kern-1)*dil` normed rows
// into the convolution's ring (LLM.md L7b).
//
// The ring is addressed by position modulo its length, which is what makes
// this a pure write. The rows a run has to leave behind are the last nine
// positions of the sequence so far; any of those that predate the run are
// already in the slots they belong in, because the run that produced them put
// them there and nothing has overwritten them since. So this dispatch only
// ever copies from `normOff`, never from the ring, and there is no slot it
// both reads and writes however short the run is — which is the case decode
// spends all its time in, where a run is one token and eight of the nine rows
// are already right.
//
// One thread is one channel of one stored row, the same shape as the
// convolution beside it. Nine rows of 10240 channels is 368 KB a run.

#include "llm_common.glsl"

layout(local_size_x = 256) in;

void main() {
    uint j = gl_WorkGroupID.y;       // which of the run's stored rows
    uint c = gl_WorkGroupID.x * gl_WorkGroupSize.x + gl_LocalInvocationID.x;
    uint wide = pc.hc * pc.nEmbd;
    uint hist = (pc.kern - 1u) * pc.dil;
    // The last min(tokens, hist) rows of the run, oldest first.
    uint keep = min(pc.tokens, hist);
    if (j >= keep || c >= wide) {
        return;
    }
    uint t = pc.tokens - keep + j;
    uint pos = SEQ_PAST + t;
    act[PLE_HIST + (pos % hist) * wide + c] = act[pc.normOff + t * wide + c];
}
EOF
