	}
	if !feat.SubgroupSizeControl || !sgs.Supported || sgs.MaxSubgroupSize < 64 {
		return fmt.Errorf("llm: the GEMM rung needs a pinned 64-wide subgroup")
	}
	for name, spirv := range map[string][]byte{
